<?php
require_once __DIR__ . '/../../includes/functions.php';
requireLogin(); requireRole(['admin','superadmin']);
$user=currentUser(); $db=getDB(); $pageTitle='Medical Records'; $isDashboard=true;
if (isGroomerAdmin($user)) { header('Location: ' . APP_URL . '/auth/unauthorized.php'); exit; }
$recordTypeColumn=$db->query("SHOW COLUMNS FROM pet_health_records LIKE 'record_type'")->fetch(PDO::FETCH_ASSOC);
if ($recordTypeColumn && str_starts_with(strtolower($recordTypeColumn['Type']), 'enum(')) $db->exec("ALTER TABLE pet_health_records MODIFY record_type VARCHAR(100) NOT NULL DEFAULT 'checkup'");
foreach (['test_performed'=>'TEXT NULL AFTER diagnosis','test_result'=>'TEXT NULL AFTER test_performed','comments'=>'TEXT NULL AFTER medications'] as $column=>$definition) {
    if (!$db->query("SHOW COLUMNS FROM pet_health_records LIKE '{$column}'")->fetch(PDO::FETCH_ASSOC)) $db->exec("ALTER TABLE pet_health_records ADD COLUMN {$column} {$definition}");
}
$prePet=(int)($_GET['pet'] ?? $_POST['pet_id'] ?? 0); $msg=''; $msgType='success'; $aiSummary=''; $aiError='';
$isSuper=$user['role_name']==='superadmin';
$petVisibility=$isSuper
    ? '(EXISTS (SELECT 1 FROM appointments a WHERE a.pet_id=p.id) OR EXISTS (SELECT 1 FROM pet_health_records hr WHERE hr.pet_id=p.id))'
    : '(EXISTS (SELECT 1 FROM appointments a JOIN clinics c ON c.id=a.clinic_id WHERE a.pet_id=p.id AND c.admin_id=?) OR EXISTS (SELECT 1 FROM pet_health_records hr JOIN veterinarians v ON v.id=hr.vet_id JOIN clinics c ON c.id=v.clinic_id WHERE hr.pet_id=p.id AND c.admin_id=?))';
$petScopeParams=$isSuper?[]:[$user['id'],$user['id']];
$petStmt=$db->prepare('SELECT p.*,CONCAT(u.first_name," ",u.last_name) AS owner_name FROM pets p JOIN users u ON u.id=p.owner_id WHERE p.is_active=1 AND '.$petVisibility.' ORDER BY p.name'); $petStmt->execute($petScopeParams); $patients=$petStmt->fetchAll();
$recordClinics=$db->prepare('SELECT id,name FROM clinics WHERE is_active=1'.($isSuper?'':' AND admin_id=?').' ORDER BY name'); $recordClinics->execute($isSuper?[]:[$user['id']]); $recordClinics=$recordClinics->fetchAll();
$preAppt=(int)($_GET['appt'] ?? 0); $appointmentPrefill=null;
if ($preAppt && $prePet) { $appointmentSql='SELECT a.id,a.pet_id,a.appointment_date,a.appointment_type,s.name AS service_name FROM appointments a LEFT JOIN services s ON s.id=a.service_id WHERE a.id=? AND a.pet_id=?'.($isSuper?'':' AND a.clinic_id IN (SELECT id FROM clinics WHERE admin_id=?)').' LIMIT 1'; $appointmentQuery=$db->prepare($appointmentSql); $appointmentQuery->execute($isSuper?[$preAppt,$prePet]:[$preAppt,$prePet,$user['id']]); $appointmentPrefill=$appointmentQuery->fetch() ?: null; if (!$appointmentPrefill) $preAppt=0; }
$canAccessPet = static function(int $petId) use ($db,$petVisibility,$petScopeParams): bool {
    $q=$db->prepare('SELECT 1 FROM pets p WHERE p.id=? AND p.is_active=1 AND '.$petVisibility.' LIMIT 1');
    $q->execute(array_merge([$petId],$petScopeParams)); return (bool)$q->fetchColumn();
};
$canAccessRecord = static function(int $recordId,int $petId) use ($db,$isSuper,$user): bool {
    $sql='SELECT 1 FROM pet_health_records hr WHERE hr.id=? AND hr.pet_id=?';
    $params=[$recordId,$petId];
    if (!$isSuper) { $sql.=' AND EXISTS (SELECT 1 FROM veterinarians v JOIN clinics c ON c.id=v.clinic_id WHERE v.id=hr.vet_id AND c.admin_id=?)'; $params[]=$user['id']; }
    $q=$db->prepare($sql.' LIMIT 1'); $q->execute($params); return (bool)$q->fetchColumn();
};

if ($_SERVER['REQUEST_METHOD']==='POST') {
    if (!verifyCsrfToken($_POST['csrf_token'] ?? '')) { $msg='Invalid request.'; $msgType='danger'; }
    elseif (!isset($_POST['add_walkin_record']) && (!$prePet || !$canAccessPet($prePet))) { $msg='Pet not found in your clinic records.'; $msgType='danger'; }
    elseif (isset($_POST['add_walkin_record'])) {
        $ownerEmail=strtolower(trim($_POST['walkin_owner_email'] ?? '')); $ownerName=trim($_POST['walkin_owner_name'] ?? ''); $ownerPhone=trim($_POST['walkin_owner_phone'] ?? ''); $selectedOwnerId=(int)($_POST['walkin_owner_id'] ?? 0); $petId=(int)($_POST['walkin_pet_id'] ?? 0); $clinicId=(int)($recordClinics[0]['id'] ?? 0); $ownerId=$selectedOwnerId;
        if ($petId) {
            $ownerQ=$db->prepare("SELECT u.id FROM pets p JOIN users u ON u.id=p.owner_id JOIN roles r ON r.id=u.role_id WHERE p.id=? AND p.is_active=1 AND r.name='pet_owner' AND u.is_active=1"); $ownerQ->execute([$petId]); $ownerId=(int)$ownerQ->fetchColumn();
            if ($ownerId && $selectedOwnerId && $ownerId!==$selectedOwnerId) $ownerId=0;
            if ($ownerId && $ownerEmail!=='') { $emailCheck=$db->prepare('SELECT 1 FROM users WHERE id=? AND LOWER(email)=?'); $emailCheck->execute([$ownerId,$ownerEmail]); if (!$emailCheck->fetchColumn()) $ownerId=0; }
        } elseif (!$ownerId && $ownerEmail!=='') {
            $ownerQ=$db->prepare("SELECT u.id FROM users u JOIN roles r ON r.id=u.role_id WHERE LOWER(u.email)=? AND r.name='pet_owner'"); $ownerQ->execute([$ownerEmail]); $ownerId=(int)$ownerQ->fetchColumn();
        }
        if (!$petId && !$ownerId && $ownerName!=='') {
            if (!$clinicId) { $msg='No active clinic is assigned to your account. Enable or assign your clinic before adding a medical record.'; $msgType='danger'; }
            elseif ($ownerEmail!=='' && !filter_var($ownerEmail,FILTER_VALIDATE_EMAIL)) { $msg='Enter a valid email address or leave it blank.'; $msgType='danger'; }
            else {
                $emailTaken=false;
                if ($ownerEmail!=='') { $emailCheck=$db->prepare('SELECT id FROM users WHERE LOWER(email)=?'); $emailCheck->execute([$ownerEmail]); $emailTaken=(bool)$emailCheck->fetchColumn(); }
                if ($emailTaken) { $msg='That email belongs to an account that is not a pet owner. Choose the registered owner or use another email.'; $msgType='danger'; }
                else {
                    $nameParts=preg_split('/\s+/', $ownerName, 2); $firstName=sanitize($nameParts[0] ?? 'Walk-in'); $lastName=sanitize($nameParts[1] ?? '');
                    $ownerRole=$db->query("SELECT id FROM roles WHERE name='pet_owner' LIMIT 1")->fetchColumn();
                    $accountEmail=$ownerEmail!=='' ? $ownerEmail : 'walkin+'.bin2hex(random_bytes(12)).'@walkin.petcare.invalid';
                    if (!$ownerRole) { $msg='Pet owner role is unavailable. Contact support.'; $msgType='danger'; }
                    else {
                        $db->prepare('INSERT INTO users (role_id,first_name,last_name,email,phone,password_hash,is_active,is_email_verified) VALUES (?,?,?,?,?,?,1,0)')->execute([(int)$ownerRole,$firstName,$lastName,$accountEmail,$ownerPhone!==''?sanitize($ownerPhone):null,hashPassword(bin2hex(random_bytes(24)))]);
                        $ownerId=(int)$db->lastInsertId();
                    }
                }
            }
        }
        $allowedClinic=false; foreach($recordClinics as $clinicRow) if((int)$clinicRow['id']===$clinicId) $allowedClinic=true;
        $ownerCheck=$db->prepare("SELECT u.id FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=? AND r.name='pet_owner' AND u.is_active=1"); $ownerCheck->execute([$ownerId]);
        $type='checkup'; $title=trim($_POST['walkin_title'] ?? ''); $date=sanitize($_POST['walkin_record_date'] ?? '');
        if ($msg!=='') { /* Keep the validation error from resolving the walk-in owner. */ }
        elseif (!$allowedClinic) { $msg='No active clinic is assigned to your account. Enable or assign your clinic before adding a medical record.'; $msgType='danger'; }
        elseif (!$ownerCheck->fetchColumn()) { $msg='Enter the walk-in owner name to create an owner profile for this pet.'; $msgType='danger'; }
        elseif ($title==='' || strlen($title)>255 || !$date || (!$petId && trim($_POST['walkin_new_pet_name'] ?? '')==='')) { $msg='Choose an existing pet or enter a new pet name, and complete the record title and date.'; $msgType='danger'; }
        else {
            if ($petId) { $petCheck=$db->prepare('SELECT id FROM pets WHERE id=? AND owner_id=? AND is_active=1'); $petCheck->execute([$petId,$ownerId]); }
            else { $db->prepare('INSERT INTO pets (owner_id,name,species,breed,gender,age_years,age_months,weight_kg) VALUES (?,?,?,?,?,?,?,?)')->execute([$ownerId,sanitize($_POST['walkin_new_pet_name']),sanitize($_POST['walkin_species'] ?? 'Dog'),sanitize($_POST['walkin_breed'] ?? ''),in_array($_POST['walkin_gender'] ?? '',['male','female','unknown'],true)?$_POST['walkin_gender']:'unknown',(int)($_POST['walkin_age_years'] ?? 0),(int)($_POST['walkin_age_months'] ?? 0),(float)($_POST['walkin_weight'] ?? 0) ?: null]); $petId=(int)$db->lastInsertId(); $petCheck=$db->prepare('SELECT id FROM pets WHERE id=? AND owner_id=?'); $petCheck->execute([$petId,$ownerId]); }
            if (!$petCheck->fetchColumn()) { $msg='That pet does not belong to the selected owner.'; $msgType='danger'; }
            else { $vetQ=$db->prepare('SELECT id FROM veterinarians WHERE clinic_id=? ORDER BY id LIMIT 1'); $vetQ->execute([$clinicId]); $vetId=(int)$vetQ->fetchColumn(); if (!$vetId) { $msg='Add a veterinarian to this clinic before saving a medical record.'; $msgType='danger'; } else { $db->prepare('INSERT INTO pet_health_records (pet_id,vet_id,record_type,title,description,diagnosis,test_performed,test_result,treatment,medications,comments,next_appointment,record_date) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$petId,$vetId,$type,sanitize($title),sanitize($_POST['walkin_description'] ?? ''),sanitize($_POST['walkin_diagnosis'] ?? ''),sanitize($_POST['walkin_test_performed'] ?? ''),sanitize($_POST['walkin_test_result'] ?? ''),sanitize($_POST['walkin_treatment'] ?? ''),sanitize($_POST['walkin_medications'] ?? ''),sanitize($_POST['walkin_comments'] ?? ''),sanitize($_POST['walkin_next_appointment'] ?? '') ?: null,$date]); $prePet=$petId; $msg='Medical record saved.'; } }
        }
    }
    elseif (isset($_POST['save_pet_note'])) {
        $note=trim($_POST['pet_note'] ?? '');
        if (!$prePet || !$canAccessPet($prePet)) { $msg='Pet not found in your clinic records.'; $msgType='danger'; }
        elseif (mb_strlen($note)>4000) { $msg='Pet note must be 4000 characters or less.'; $msgType='danger'; }
        else { $db->prepare('UPDATE pets SET notes=? WHERE id=?')->execute([$note ?: null,$prePet]); $msg='Pet note saved.'; }
    }
    elseif (isset($_POST['generate_summary'])) {
        if (!$canAccessPet($prePet)) { $aiError='This pet is not in your clinic records.'; }
        else {
            $petQ=$db->prepare('SELECT p.* FROM pets p WHERE p.id=?'); $petQ->execute([$prePet]); $pet=$petQ->fetch();
            $historySql='SELECT hr.record_type,hr.title,hr.description,hr.diagnosis,hr.test_performed,hr.test_result,hr.treatment,hr.medications,hr.comments,hr.record_date,hr.next_appointment FROM pet_health_records hr WHERE hr.pet_id=?'.($isSuper?'':' AND EXISTS (SELECT 1 FROM veterinarians v JOIN clinics c ON c.id=v.clinic_id WHERE v.id=hr.vet_id AND c.admin_id=?)').' ORDER BY hr.record_date DESC';
            $historyQ=$db->prepare($historySql); $historyQ->execute($isSuper?[$prePet]:[$prePet,$user['id']]); $history=$historyQ->fetchAll();
            $historyText=$history ? implode("\n",array_map(static fn($r)=>implode(' | ',array_filter([$r['record_date'].' '.$r['record_type'],$r['title'],$r['description'],$r['diagnosis'],$r['test_performed'],$r['test_result'],$r['treatment'],$r['medications'],$r['comments'],$r['next_appointment']?'Next appointment: '.$r['next_appointment']:''])), $history)) : 'No medical records are available yet.';
            $prompt="Summarize this pet's complete documented medical record history in a concise, neutral paragraph. Use only facts in the records, do not add diagnosis or treatment advice, and state if no history is recorded. This is a chart summary, not a diagnosis.\n\nPet: {$pet['name']}\nSpecies: {$pet['species']}\nBreed: {$pet['breed']}\nHistory:\n{$historyText}";
            $ai=callGroq($prompt,350);
            if ($ai['success']) { $aiSummary=trim($ai['text']); }
            else $aiError=$ai['text'];
        }
    }
    elseif (isset($_POST['add_record'])) {
        $type='checkup'; $title=trim($_POST['title'] ?? ''); $date=sanitize($_POST['record_date'] ?? '');
        if ($type==='' || strlen($type)>100 || $title==='' || !$date) { $msg='Record type, title, and date are required.'; $msgType='danger'; }
        else {
            $staffQuery=$db->prepare('SELECT v.id FROM veterinarians v JOIN clinics c ON c.id=v.clinic_id'.($isSuper?'':' WHERE c.admin_id=?').' ORDER BY v.id LIMIT 1'); $staffQuery->execute($isSuper?[]:[$user['id']]); $recordVetId=(int)$staffQuery->fetchColumn();
            $db->prepare('INSERT INTO pet_health_records (pet_id,vet_id,record_type,title,description,diagnosis,test_performed,test_result,treatment,medications,comments,next_appointment,record_date) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$prePet,$recordVetId ?: null,$type,sanitize($title),sanitize($_POST['description'] ?? ''),sanitize($_POST['diagnosis'] ?? ''),sanitize($_POST['test_performed'] ?? ''),sanitize($_POST['test_result'] ?? ''),sanitize($_POST['treatment'] ?? ''),sanitize($_POST['medications'] ?? ''),sanitize($_POST['comments'] ?? ''),sanitize($_POST['next_appointment'] ?? '') ?: null,$date]);
            $msg='Medical record added.';
        }
    } elseif (isset($_POST['update_record'])) {
        $id=(int)($_POST['record_id'] ?? 0); $type='checkup'; $title=trim($_POST['title'] ?? ''); $date=sanitize($_POST['record_date'] ?? '');
        if (!$canAccessRecord($id,$prePet)) { $msg='Medical record not found in your clinic.'; $msgType='danger'; }
        elseif ($type==='' || strlen($type)>100 || $title==='' || !$date) { $msg='Record type, title, and date are required.'; $msgType='danger'; }
        else { $db->prepare('UPDATE pet_health_records SET title=?,description=?,diagnosis=?,test_performed=?,test_result=?,treatment=?,medications=?,comments=?,record_date=? WHERE id=? AND pet_id=?')->execute([sanitize($title),sanitize($_POST['description'] ?? ''),sanitize($_POST['diagnosis'] ?? ''),sanitize($_POST['test_performed'] ?? ''),sanitize($_POST['test_result'] ?? ''),sanitize($_POST['treatment'] ?? ''),sanitize($_POST['medications'] ?? ''),sanitize($_POST['comments'] ?? ''),$date,$id,$prePet]); $msg='Medical record updated.'; }
    } elseif (isset($_POST['delete_record'])) {
        $id=(int)($_POST['record_id'] ?? 0); if (!$canAccessRecord($id,$prePet)) { $msg='Medical record not found in your clinic.'; $msgType='danger'; } else { $db->prepare('DELETE FROM pet_health_records WHERE id=? AND pet_id=?')->execute([$id,$prePet]); $msg='Medical record deleted.'; }
    }
}

$selectedPet=null; $records=[];
if ($prePet && $canAccessPet($prePet)) {
    $q=$db->prepare('SELECT p.*,CONCAT(u.first_name," ",u.last_name) owner_name FROM pets p JOIN users u ON u.id=p.owner_id WHERE p.id=?'); $q->execute([$prePet]); $selectedPet=$q->fetch();
    if ($selectedPet) { $recordSql='SELECT hr.*,CONCAT(u.first_name," ",u.last_name) AS vet_name FROM pet_health_records hr LEFT JOIN veterinarians v ON v.id=hr.vet_id LEFT JOIN users u ON u.id=v.user_id WHERE hr.pet_id=?'.($isSuper?'':' AND EXISTS (SELECT 1 FROM veterinarians scoped_v JOIN clinics c ON c.id=scoped_v.clinic_id WHERE scoped_v.id=hr.vet_id AND c.admin_id=?)').' ORDER BY hr.record_date DESC,hr.id DESC'; $q=$db->prepare($recordSql); $q->execute($isSuper?[$prePet]:[$prePet,$user['id']]); $records=$q->fetchAll(); }
}
?>
