tions'] ?? '') ?></textarea><label class="form-label">Comments / Notes</label><textarea name="comments" class="form-control"><?= sanitize($r['comments'] ?? '') ?></textarea><button class="btn btn-primary btn-sm">Save</button></form><form method="POST" onsubmit="return confirm('Delete this record?')"><?= csrfField() ?><input type="hidden" name="pet_id" value="<?= (int)$selectedPet['id'] ?>"><input type="hidden" name="record_id" value="<?= (int)$r['id'] ?>"><button name="delete_record" value="1" class="btn btn-danger btn-sm">Delete</button></form></details></td></tr><?php endforeach; ?>
