<?php foreach($records as $r): ?><div class="modal-overlay" id="adminRecordView<?= (int)$r['id'] ?>"><div class="modal" style="max-width:760px;max-height:85vh;overflow:auto;"><div class="modal-header"><div><h3><?= sanitize($r['title']) ?></h3><small style="color:var(--text-muted)"><?= date('M j, Y',strtotime($r['record_date'])) ?> · <?= sanitize(ucfirst($r['record_type'])) ?> · Added by <?= sanitize($r['vet_name'] ?: 'Unknown veterinarian') ?></small></div><button class="modal-close" type="button" onclick="closeModal('adminRecordView<?= (int)$r['id'] ?>')"><i class="fas fa-times"></i></button></div><div class="modal-body" style="display:grid;grid-template-columns:1fr 1fr;gap:1rem;"><?php foreach(['Description'=>'description','Diagnosis'=>'diagnosis','Test Performed'=>'test_performed','Test Result'=>'test_result','Action'=>'treatment','Medication'=>'medications','Comments / Notes'=>'comments'] as $label=>$field): ?><section style="padding:.85rem;background:var(--bg);border-radius:10px;min-height:90px;"><strong style="display:block;margin-bottom:.4rem;"><?= $label ?></strong><div style="white-space:pre-wrap;color:var(--text-muted)"><?= trim((string)($r[$field] ?? ''))!=='' ? nl2br(sanitize($r[$field])) : '—' ?></div></section><?php endforeach; ?></div></div></div><?php endforeach; ?>
<?php endif; ?></div></div>
