s="form-group"><label class="form-label">Age years</label><input type="number" min="0" name="walkin_age_years" class="form-control"></div><div class="form-group"><label class="form-label">Age months</label><input type="number" min="0" max="11" name="walkin_age_months" class="form-control"></div><div class="form-group"><label class="form-label">Weight kg</label><input type="number" min="0" step="0.01" name="walkin_weight" class="form-control"></div></div></div><input type="hidden" name="walkin_record_type" value="checkup"><div class="form-row"><div class="form-group"><label class="form-label">Title</label><input name="walkin_title" class="form-control" required maxlength="255"></div><div class="form-group"><label class="form-label">Record date</label><input type="date" name="walkin_record_date" class="form-control" value="<?= date('Y-m-d') ?>" required></div></div><div class="form-row"><div class="form-group"><label class="form-label">Description</label><textarea name="walkin_description" class="form-control"></textarea></div><div class="form-group"><label class="form-label">Diagnosis</label><textarea name="walkin_diagnosis" class="form-control"></textarea></div></div><div class="form-row"><div class="form-group"><label class="form-label">Test Performed</label><textarea name="walkin_test_performed" class="form-control"></textarea></div><div class="form-group"><label class="form-label">Test Result</label><textarea name="walkin_test_result" class="form-control"></textarea></div></div><div class="form-row"><div class="form-group"><label class="form-label">Action</label><textarea name="walkin_treatment" class="form-control"></textarea></div><div class="form-group"><label class="form-label">Medication</label><textarea name="walkin_medications" class="form-control"></textarea></div></div><div class="form-group"><label class="form-label">Comments / Notes</label><textarea name="walkin_comments" class="form-control"></textarea></div><div class="modal-footer"><button type="button" class="btn btn-outline" onclick="closeModal('adminWalkinModal')">Cancel</button><button class="btn btn-primary">Save Medical Record</button></div></form></div></div></div>
